<?php require __DIR__.'/koneksi.php';[$rows,$total]=cart_data($koneksi);if(!$rows)redirect('keranjang.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$nama=trim($_POST['nama']??'');$email=trim($_POST['email']??'');$telepon=trim($_POST['telepon']??'');$alamat=trim($_POST['alamat']??'');if(!$nama||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$telepon||!$alamat){$error='Lengkapi nama, email valid, telepon, dan alamat.';}else{try{$koneksi->begin_transaction();$fresh=[];$sum=0;$lock=$koneksi->prepare('SELECT id_produk,nama_produk,harga,stok FROM produk WHERE id_produk=? FOR UPDATE');foreach($_SESSION['cart'] as $id=>$qty){$id=(int)$id;$qty=(int)$qty;$lock->bind_param('i',$id);$lock->execute();$p=$lock->get_result()->fetch_assoc();if(!$p||$qty<1||$qty>(int)$p['stok'])throw new Exception('Stok produk berubah. Periksa keranjang.');$p['jumlah']=$qty;$p['subtotal']=$qty*$p['harga'];$sum+=$p['subtotal'];$fresh[]=$p;}$ins=$koneksi->prepare("INSERT INTO pesanan(nama_pembeli,email,telepon,alamat,total_harga,status) VALUES(?,?,?,?,?,'baru')");$ins->bind_param('ssssd',$nama,$email,$telepon,$alamat,$sum);$ins->execute();$order=$koneksi->insert_id;$detail=$koneksi->prepare('INSERT INTO detail_pesanan(id_pesanan,id_produk,nama_produk,harga,jumlah,subtotal) VALUES(?,?,?,?,?,?)');$stock=$koneksi->prepare('UPDATE produk SET stok=stok-? WHERE id_produk=? AND stok>=?');foreach($fresh as $p){$detail->bind_param('iisdid',$order,$p['id_produk'],$p['nama_produk'],$p['harga'],$p['jumlah'],$p['subtotal']);$detail->execute();$stock->bind_param('iii',$p['jumlah'],$p['id_produk'],$p['jumlah']);$stock->execute();if($stock->affected_rows!==1)throw new Exception('Stok tidak cukup.');}$koneksi->commit();unset($_SESSION['cart']);redirect('sukses.php?id='.$order.'&token='.hash_hmac('sha256',(string)$order,session_id()));}catch(Throwable $e){$koneksi->rollback();$error='Pesanan gagal: '.e($e->getMessage());}}}$page_title='Checkout';require __DIR__.'/partials/header.php';?><main class="container py-5"><h2>Checkout</h2><?php if($error):?><div class="alert alert-danger"><?=$error?></div><?php endif;?><div class="row g-4"><div class="col-md-7"><form method="post" class="soft-card p-4"><input type="hidden" name="csrf" value="<?=csrf()?>"><?php foreach(['nama'=>'Nama pembeli','email'=>'Email','telepon'=>'Nomor telepon'] as $key=>$label):?><label class="form-label"><?=$label?></label><input class="form-control mb-3" name="<?=$key?>" value="<?=e($_POST[$key]??'')?>" <?= $key==='email'?'type="email"':'type="text"' ?> required><?php endforeach;?><label class="form-label">Alamat pengiriman</label><textarea name="alamat" class="form-control mb-3" required><?=e($_POST['alamat']??'')?></textarea><button class="btn btn-pink">Buat Pesanan</button></form></div><div class="col-md-5"><div class="soft-card p-4"><h5>Ringkasan</h5><?php foreach($rows as $p):?><p><?=e($p['nama_produk'])?> × <?=$p['jumlah']?> <span class="float-end"><?=money($p['subtotal'])?></span></p><?php endforeach;?><hr><h5>Total: <?=money($total)?></h5><small class="text-muted">Demo pesanan, belum termasuk pembayaran online.</small></div></div></div></main><?php require __DIR__.'/partials/footer.php';?>
